        for (int32_t blockStart = start_; blockStart < end_; blockStart += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (blockStart + BLOCK_SIZE > totalElements_) {
                valid = totalElements_ - blockStart;
            }

            // CopyIn: load input tile from GM to UB
            // Compute: GELU in float32
            // CopyOut: store output tile from UB to GM

            // Allocate UB buffers
            LocalTensor<T> xTyped = ...;  // typed input buffer
            LocalTensor<float> xFp32 = ...;  // float32 compute buffer
            LocalTensor<float> xPow3 = ...;
            LocalTensor<float> uBuf = ...;
            LocalTensor<float> expBuf = ...;
            LocalTensor<float> oneBuf = ...;
            LocalTensor<float> denomBuf = ...;
            LocalTensor<float> yFp32 = ...;
            LocalTensor<T> yTyped = ...;

            // CopyIn
            DataCopy(xTyped, xGm[blockStart], valid);

            // Cast to float32 if needed
            if constexpr (!std::is_same_v<T, float>) {
                Cast(xFp32, xTyped, CAST_NONE, valid);
            } else {
