```cpp
template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(
        GlobalTensor<T> xGm, GlobalTensor<T> yGm,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGm_ = xGm;
        yGm_ = yGm;
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        constexpr int32_t blockSize = 2048;

        // Allocate UB buffers (fixed size)
        TQue<T> inQueue;
        TQue<T> outQueue;
        TBuf<float> xFp32Buf;
        TBuf<float> xPow3Buf;
        TBuf<float> uBuf;
        TBuf<float> expBuf;
        TBuf<float> oneBuf;
        TBuf<float> denomBuf;
        TBuf<float> yFp32Buf;

        // Allocate memory
        inQueue.AllocBuf(blockSize);
        outQueue.AllocBuf(blockSize);
        xFp32Buf.AllocBuf(blockSize);
        xPow3Buf.AllocBuf(blockSize);
        uBuf.AllocBuf(blockSize);
        expBuf.AllocBuf(blockSize);
        oneBuf.AllocBuf(blockSize);
        denomBuf.AllocBuf(blockSize);
        yFp32Buf.AllocBuf(blockSize);

        for (int32_t offset = blockStart_; offset < blockEnd_; offset += blockSize) {
            int32_t valid = blockSize;
            if (offset + blockSize > totalElements_) {
                valid = totalElements_ - offset;
            }

            // CopyIn: GM → UB
            LocalTensor<T> xTyped = inQueue.AllocTensor<T>();
            DataCopy(xTyped, xGm_[offset], valid);
            inQueue.EnQue(xTyped);
            LocalTensor<T> xIn = inQueue.DeQue<T>();

            // Cast to float32
            if constexpr (std::is_same_v<T, float>) {
                // Already float32, copy to compute buffer
                DataCopy(xFp32Buf, xIn, valid);
            } else {
                Cast(xFp32Buf, xIn, CAST_NONE, valid);
            }

            // Compute GELU in float32
            // x^3 = x * x * x
            Mul(xPow3Buf, xFp32Buf, xFp32Buf);
            Mul(xPow3Buf, xPow3Buf, xFp32Buf);
            // u = scale * (x + 0.044715 * x^3)
            Muls(xPow3Buf, xPow3Buf, CUBIC);
            Add(uBuf, xFp32Buf, xPow3Buf);
            Muls(uBuf, uBuf, SCALE);
            // denom = 1 + exp(-2u)
            Muls(expBuf, uBuf, -2.0f);
            Exp(expBuf, expBuf);
            // Fill oneBuf with 1.0f
            // denom = oneBuf + expBuf
            // But we need to copy 1.0f to oneBuf first
            // There's Fill API: Fill(oneBuf, 1.0f, valid)
            // Or I can use a scalar multiply: Mul(oneBuf, oneBuf, ...) no, that doesn't work
            // Actually, there's T.tile.fill equivalent in AscendC
