            // y = x / denom
            Div(yFp32Buf, xFp32Buf, denomBuf);

            // Cast back to typed
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(outQueue, yFp32Buf, valid);
            } else {
                Cast(outQueue, yFp32Buf, CAST_ROUND, valid);
            }
            outQueue.EnQue();
            LocalTensor<T> yOut = outQueue.DeQue<T>();
            DataCopy(yGm_[offset], yOut, valid);

            // Free buffers
            if constexpr (std::is_same_v<T, float>) {
                // Nothing to free, buffers are reused
            } else {
                // Buffers are reused next iteration
            }
        }
    }

private:
