Here's the simplified kernel:

```cpp
template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(
        GlobalTensor<T> xGm, GlobalTensor<T> yGm,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGm_ = xGm;
        yGm_ = yGm;
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        constexpr int32_t blockSize = 2048;

        // Allocate UB compute buffers
        TBuf<T> xTypedBuf;
        xTypedBuf.AllocBuf(blockSize);

        TBuf<float> xFp32Buf;
        xFp32Buf.AllocBuf(blockSize);

        TBuf<float> xPow3Buf;
        xPow3Buf.AllocBuf(blockSize);

        TBuf<float> uBuf;
        uBuf.AllocBuf(blockSize);

        TBuf<float> expBuf;
        expBuf.AllocBuf(blockSize);

        TBuf<float> oneBuf;
        oneBuf.AllocBuf(blockSize);

        TBuf<float> denomBuf;
        denomBuf.AllocBuf(blockSize);

        TBuf<float> yFp32Buf;
        yFp32Buf.AllocBuf(blockSize);

        TBuf<T> yTypedBuf;
        yTypedBuf.AllocBuf(blockSize);

        for (int32_t offset = blockStart_; offset < blockEnd_; offset += blockSize) {
            int32_t valid = blockSize;
            if (offset + blockSize > totalElements_) {
                valid = totalElements_ - offset;
            }

            // CopyIn: GM → UB
            DataCopy(xTypedBuf, xGm_[offset], valid);
            PipeBarrier<PIPE_ALL>();

            // Cast to float32
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(xFp32Buf, xTypedBuf, valid);
            } else {
                Cast(xFp32Buf, xTypedBuf, CAST_NONE, valid);
            }
            PipeBarrier<PIPE_ALL>();

            // Compute GELU in float32
            // x^3 = x * x * x
            Mul(xPow3Buf, xFp32Buf, xFp32Buf);
            Mul(xPow3Buf, xPow3Buf, xFp32Buf);
            // u = scale * (x + 0.044715 * x^3)
            Muls(xPow3Buf, xPow3Buf, CUBIC);
            Add(uBuf, xFp32Buf, xPow3Buf);
            Muls(uBuf, uBuf, SCALE);
            // denom = 1 + exp(-2u)
            Muls(expBuf, uBuf, -2.0f);
            Exp(expBuf, expBuf);
            Fill(oneBuf, 1.0f, valid);
            Add(denomBuf, oneBuf, expBuf);
            // y = x / denom
            Div(yFp32Buf, xFp32Buf, denomBuf);
            PipeBarrier<PIPE_ALL>();

            // Cast back to typed
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(yTypedBuf, yFp32Buf, valid);
            } else {
                Cast(yTypedBuf, yFp32Buf, CAST_ROUND, valid);
            }
            PipeBarrier<PIPE_ALL>();

            // CopyOut: UB → GM
            DataCopy(yGm_[offset], yTypedBuf, valid);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGm_;
    GlobalTensor<T> yGm_;
    int32_t totalElements_;
    int32_t blockStart_;
    int32_t blockEnd_;

    static constexpr float SCALE = 0.79788456f;
    static constexpr float CUBIC = 0.044715f;
};
```

