{"content": "#include "ascendc/ascendc.h"

using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;
constexpr float CUBIC = 0.044715f;
constexpr float NEG_2_SCALE = -1.59576912f;  // -2.0 * sqrt(2/pi)

template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(
        GlobalTensor<T> xGm, GlobalTensor<T> yGm,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGm_ = xGm;
        yGm_ = yGm;
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        uint32_t fp32Sz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(float));
        uint32_t ioSz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(T));

        TBuf<T> xTyped;   xTyped.AllocBuf(ioSz);
        TBuf<float> xIn;  xIn.AllocBuf(fp32Sz);
        TBuf<float> work; work.AllocBuf(fp32Sz);
        TBuf<float> one;  one.AllocBuf(fp32Sz);
        TBuf<float> denom; denom.AllocBuf(fp32Sz);
        TBuf<float> yFp32; yFp32.AllocBuf(fp32Sz);
        TBuf<T> yTyped;   yTyped.AllocBuf(ioSz);

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32 = static_cast<uint32_t>(valid);

            // CopyIn: GM -> UB
            DataCopy(xTyped, xGm_[off], u32);
            PipeBarrier<PIPE_ALL>();

            // Cast to float32
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(xIn, xTyped, u32);
            } else {
                Cast(xIn, xTyped, CAST_NONE, u32);
            }
            PipeBarrier<PIPE_ALL>();

            // GELU(x) = x / (1 + exp(-2u)), u = scale*(x + cubic*x^3)
            // work = x^2
            Mul(work, xIn, xIn);
            // work = x^3
            Mul(work, work, xIn);
            // work = 0.044715 * x^3
            Muls(work, work, CUBIC);
            // work = x + 0.044715*x^3  (original x still in xIn)
            Add(work, xIn, work);
            // work = -2 * u  (work now holds -2u)
            Muls(work, work, NEG_2_SCALE);
            // work = exp(-2u)
            Exp(work, work);
            // one = 1.0
            Fill(one, 1.0f, u32);
            // denom = 1 + exp(-2u)
            Add(denom, one, work);
            // yFp32 = x / (1 + exp(-2u)) = GELU(x)
            Div(yFp32, xIn, denom);
            PipeBarrier<PIPE_ALL>();

            // Cast back to typed
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(yTyped, yFp32, u32);
            } else {
                Cast(yTyped, yFp32, CAST_ROUND, u32);
            }
            PipeBarrier<PIPE_ALL>();

            // CopyOut: UB -> GM
            DataCopy(yGm_[off], yTyped, u32);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGm_;
    GlobalTensor<T> yGm_;
    int32_t totalElements_;
    int32_t blockStart_;
    int32_t blockEnd_;
};

