#include "tiling/platform/platform_ascendc.h"

constexpr int32_t BLOCK_SIZE = 2048;
constexpr int32_t MAX_CORES = 20;

at::Tensor gelu(const at::Tensor& x, c10::optional<std::string> approximate)
{
    TORCH_CHECK(x.is_contiguous(), "GELU input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "GELU unsupported dtype, expected float32/float16/bfloat16");

    int32_t totalElements = static_cast<int32_t>(x.numel());
    int32_t numBlocks = (totalElements + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int32_t usedCores = std::min(MAX_CORES, numBlocks);
    int32_t tasksPerCore = (numBlocks + usedCores - 1) / usedCores;

    auto y = at::empty_like(x);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(
        [&]() {
            // Return a dummy context - the actual platform info is obtained internally
            at::NoGradGuard no_grad;
            auto temp = x.template to(at::kCPU);
            return temp;
        }());

    // Dispatch by dtype
    if (x.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(gelu_fp32, usedCores, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
    } else if (x.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(gelu_fp16, usedCores, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
    } else if (x.scalar_type() == at::kBFloat16) {
        EXEC_KERNEL_CMD(gelu_bf16, usedCores, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
    }

    return y;
}
