constexpr int32_t BLOCK_SIZE = 2048;
constexpr float SCALE = 0.79788456f;
constexpr float CUBIC = 0.044715f;
constexpr float NEG_2_SCALE = -1.59576912f;

template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        TBuf<TPosition::VECCALC> xTypedBuf;
        TBuf<TPosition::VECCALC> xFp32Buf;
        TBuf<TPosition::VECCALC> workBuf;
        TBuf<TPosition::VECCALC> oneBuf;
        TBuf<TPosition::VECCALC> denomBuf;
        TBuf<TPosition::VECCALC> yFp32Buf;

        uint32_t fp32Sz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(float));
        uint32_t ioSz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(T));

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32 = static_cast<uint32_t>(valid);

            // CopyIn: GM → UB
            LocalTensor<T> xTyped = xTypedBuf.Get<T>();
            AscendC::DataCopyExtParams copyParams{1, u32 * sizeof(T), 0, 0, 0};
            AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(xTyped, xGM_[off], copyParams, padParams);
            PipeBarrier<PIPE_ALL>();

            // Cast to float32
            if constexpr (std::is_same_v<T, float>) {
                xFp32Buf.Get<float>() = xTyped.ReinterpretCast<float>();
            } else {
                LocalTensor<float> xFp32 = xFp32Buf.Get<float>();
                AscendC::Cast(xFp32, xTyped, RoundMode::CAST_NONE, u32);
                PipeBarrier<PIPE_V>();
            }

            // Compute GELU
            LocalTensor<float> xFp32 = (std::is_same_v<T, float>) ? xTyped.ReinterpretCast<float>() : xFp32Buf.Get<float>();
            LocalTensor<float> work = workBuf.Get<float>();
            LocalTensor<float> one = oneBuf.Get<float>();
            LocalTensor<float> denom = denomBuf.Get<float>();
            LocalTensor<float> yFp32 = yFp32Buf.Get<float>();

            // x^3
            Mul(work, xFp32, xFp32);       // x^2
            Mul(work, work, xFp32);         // x^3
            Muls(work, work, CUBIC);        // 0.044715 * x^3
            Add(work, xFp32, work);         // x + 0.044715 * x^3
            Muls(work, work, NEG_2_SCALE);  // -2u
            Exp(work, work);                // exp(-2u)
