For the kernel class:
```cpp
template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        AscendC::TBuf<AscendC::TPosition::VECCALC> xTypedBuf;
        AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf;
        AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf;
        AscendC::TBuf<AscendC::TPosition::VECCALC> oneBuf;
        AscendC::TBuf<AscendC::TPosition::VECCALC> denomBuf;
        AscendC::TBuf<AscendC::TPosition::VECCALC> yFp32Buf;

        uint32_t fp32Sz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(float));
        uint32_t ioSz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(T));

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32 = static_cast<uint32_t>(valid);

            // CopyIn
            AscendC::LocalTensor<T> xTyped = xTypedBuf.Get<T>();
            AscendC::DataCopyExtParams copyParams{1, u32 * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(xTyped, xGM_[off], copyParams, padParams);
            AscendC::PipeBarrier<AscendC::PIPE_ALL>();

            // Cast to float32
            AscendC::LocalTensor<float> xFp32;
            if constexpr (std::is_same_v<T, float>) {
                xFp32 = xTyped.template ReinterpretCast<float>();
            } else {
                xFp32 = xFp32Buf.Get<float>();
                AscendC::Cast(xFp32, xTyped, AscendC::RoundMode::CAST_NONE, u32);
                AscendC::PipeBarrier<AscendC::PIPE_V>();
            }

            // Compute GELU
            AscendC::LocalTensor<float> work = workBuf.Get<float>();
            AscendC::LocalTensor<float> one = oneBuf.Get<float>();
            AscendC::LocalTensor<float> denom = denomBuf.Get<float>();
            AscendC::LocalTensor<float> yFp32 = yFp32Buf.Get<float>();

            AscendC::Mul(work, xFp32, xFp32);        // x^2
            AscendC::Mul(work, work, xFp32);          // x^3
            AscendC::Muls(work, work, CUBIC);         // 0.044715 * x^3
            AscendC::Add(work, xFp32, work);          // x + 0.044715*x^3
            AscendC::Muls(work, work, NEG_2_SCALE);   // -2u
            AscendC::Exp(work, work);                 // exp(-2u)
            AscendC::Fill(one, 1.0f, u32);            // 1.0
            AscendC::Add(denom, one, work);           // 1 + exp(-2u)
            AscendC::Div(yFp32, xFp32, denom);        // GELU(x)
            AscendC::PipeBarrier<AscendC::PIPE_ALL>();

            // CopyOut
            if constexpr (std::is_same_v<T, float>) {
                AscendC::LocalTensor<T> yTyped = yFp32.template ReinterpretCast<T>();
                AscendC::DataCopyExtParams copyOut{1, u32 * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                AscendC::DataCopyPad(yGM_[off], yTyped, copyOut);
            } else {
                AscendC::LocalTensor<T> yTyped = xTypedBuf.Get<T>();
