Here's my final kernel design:

```cpp
#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;
constexpr float CUBIC = 0.044715f;
constexpr float NEG_2_SCALE = -1.59576912f;

template <typename T>
class GELUKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
    }

    __aicore__ inline void Process()
    {
        TBuf<TPosition::VECCALC> xTypedBuf;
        TBuf<TPosition::VECCALC> xFp32Buf;
        TBuf<TPosition::VECCALC> workBuf;
        TBuf<TPosition::VECCALC> oneBuf;
        TBuf<TPosition::VECCALC> denomBuf;
        TBuf<TPosition::VECCALC> yFp32Buf;

        uint32_t fp32Sz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(float));
        uint32_t ioSz = static_cast<uint32_t>(BLOCK_SIZE * sizeof(T));

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32 = static_cast<uint32_t>(valid);

            // CopyIn
            LocalTensor<T> xTyped = xTypedBuf.Get<T>();
            DataCopyExtParams cp{1, u32 * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
            DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
            DataCopyPad(xTyped, xGM_[off], cp, pad);
            PipeBarrier<PIPE_ALL>();

            // Cast to float32
            LocalTensor<float> xFp32;
            if constexpr (std::is_same_v<T, float>) {
                xFp32 = xTyped.template ReinterpretCast<float>();
            } else {
                xFp32 = xFp32Buf.Get<float>();
                Cast(xFp32, xTyped, RoundMode::CAST_NONE, u32);
                PipeBarrier<PIPE_V>();
            }

            // Compute
            LocalTensor<float> w = workBuf.Get<float>();
            LocalTensor<float> one = oneBuf.Get<float>();
            LocalTensor<float> denom = denomBuf.Get<float>();
            LocalTensor<float> yFp32 = yFp32Buf.Get<float>();

            Mul(w, xFp32, xFp32);        // x^2
            Mul(w, w, xFp32);            // x^3
            Muls(w, w, CUBIC);           // 0.044715*x^3
            Add(w, xFp32, w);            // x + 0.044715*x^3
            Muls(w, w, NEG_2_SCALE);     // -2u
            Exp(w, w);                   // exp(-2u)
            Fill(one, 1.0f, u32);        // 1.0
            Add(denom, one, w);          // 1+exp(-2u)
            Div(yFp32, xFp32, denom);    // GELU(x)
            PipeBarrier<PIPE_ALL>();

            // CopyOut
            if constexpr (std::is_same_v<T, float>) {
                LocalTensor<T> yTyped = yFp32.template ReinterpretCast<T>();
                DataCopyExtParams cpOut{1, u32 * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                DataCopyPad(yGM_[off], yTyped, cpOut);
            } else {
                LocalTensor<T> yTyped = xTypedBuf.Get<T>();
                Cast(yTyped, yFp32, RoundMode::CAST_ROUND, u32);
                PipeBarrier<PIPE_V>();
                DataCopyExtParams cpOut{1, u32 * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
                DataCopyPad(yGM_[off], yTyped, cpOut);
            }
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    int32_t totalElements_;
    int32_t blockStart_;
    int32_t blockEnd_;
};

extern "C" __global__ __aicore__ void gelu_fp16(
    GM_ADDR x, GM_ADDR y,
    int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    GELUKernel<half> k; k.Init(x, y, totalElements, start, end); k.Process();
}

extern "C" __global__ __aicore__ void gelu_fp32(
    GM_ADDR x, GM_ADDR y,
    int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    GELUKernel<float> k; k.Init(x, y, totalElements, start, end); k.Process();
}

extern "C" __global__ __aicore__ void gelu_bf16(
    GM_ADDR x, GM_ADDR y,
    int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    GELUKernel<bfloat16_t> k; k.Init(x, y, totalElements, start, end); k.Process();
}
