using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() {}
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockStart, int32_t blockEnd,
        uint32_t tmpBufSize, TPipe* pipe)
    {
        pipe_ = pipe;
        totalElements_ = totalElements;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        pipe_->InitBuffer(inQueueX_, 1, static_cast<uint32_t>(BLOCK_SIZE * sizeof(T)));
        pipe_->InitBuffer(outQueue_, 1, static_cast<uint32_t>(BLOCK_SIZE * sizeof(T)));
        if (tmpBufSize > 0) {
            pipe_->InitBuffer(bufQueue_, tmpBufSize);
        }
    }
    __aicore__ inline void Process()
    {
        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            CopyIn(valid, off);
            Compute(valid);
            CopyOut(valid, off);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t valid, int32_t off)
    {
        LocalTensor<T> srcLocal = inQueueX_.AllocTensor<T>();
        DataCopy(srcLocal, xGM_[off], static_cast<uint32_t>(valid));
        inQueueX_.EnQue(srcLocal);
    }
    __aicore__ inline void Compute(int32_t valid)
    {
        LocalTensor<T> dstLocal = outQueue_.AllocTensor<T>();
        LocalTensor<T> srcLocal = inQueueX_.DeQue<T>();
        LocalTensor<uint8_t> tmpLocal;
        if (bufQueue_.Get<uint8_t>() != nullptr) {
            tmpLocal = bufQueue_.Get<uint8_t>();
            Gelu(dstLocal, srcLocal, tmpLocal, static_cast<uint32_t>(valid));
        } else {
            Gelu(dstLocal, srcLocal, static_cast<uint32_t>(valid));
        }
        outQueue_.EnQue<T>(dstLocal);
        inQueueX_.FreeTensor(srcLocal);
    }
    __aicore__ inline void CopyOut(int32_t valid, int32_t off)
    {
        LocalTensor<T> dstLocal = outQueue_.DeQue<T>();
        DataCopy(yGM_[off], dstLocal, static_cast<uint32_t>(valid));
        outQueue_.FreeTensor(dstLocal);
    }

    AscendC::TPipe* pipe_;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inQueueX_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufQueue_;
    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    int32_t totalElements_;
    int32_t blockStart_;
    int32_t blockEnd_;
};

extern "C" __global__ __aicore__ void gelu_fp16(
    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
