constexpr int32_t BLOCK_SIZE = 2048;
constexpr int32_t MAX_CORES = 20;

at::Tensor gelu(const at::Tensor& x, c10::optional<std::string> approximate)
{
    TORCH_CHECK(x.is_contiguous(), "GELU input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "GELU unsupported dtype, expected float32/float16/bfloat16");

    int32_t totalElements = static_cast<int32_t>(x.numel());
    int32_t numBlocks = (totalElements + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int32_t usedCores = std::min(MAX_CORES, numBlocks);
    int32_t tasksPerCore = (numBlocks + usedCores - 1) / usedCores;

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t aivCoreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    if (aivCoreNum <= 0) aivCoreNum = MAX_CORES;
    usedCores = std::min(aivCoreNum, numBlocks);
    tasksPerCore = (numBlocks + usedCores - 1) / usedCores;

    uint32_t blockDim = static_cast<uint32_t>(usedCores);

    if (x.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(gelu_fp32, blockDim, x, x, totalElements, BLOCK_SIZE, tasksPerCore);
        return x;
    } else if (x.scalar_type() == at::kHalf) {
        auto y = at::empty_like(x);
        EXEC_KERNEL_CMD(gelu_fp16, blockDim, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
        return y;
    } else if (x.scalar_type() == at::kBFloat16) {
        // Convert bf16 to fp16 for kernel, then back
        at::Tensor xFp16 = x.to(at::kHalf);
        at::Tensor yFp16 = at::empty_like(xFp16);
        EXEC_KERNEL_CMD(gelu_fp16, blockDim, xFp16, yFp16, totalElements, BLOCK_SIZE, tasksPerCore);
        return yFp16.to(at::kBFloat16);
    }

    return at::empty_like(x);
}
