```cpp
#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;
constexpr int32_t TABLE_SIZE = 1024;

template <typename T>
class KernelGeluTable {
public:
    __aicore__ inline KernelGeluTable() = default;
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR table,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd,
        float minVal, float maxVal)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        tableGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(table), TABLE_SIZE);
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
        totalElements_ = totalElements;
        minVal_ = minVal;
        maxVal_ = maxVal;
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t ubBufSize = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(T);
        constexpr uint32_t tableBufSize = static_cast<uint32_t>(TABLE_SIZE) * sizeof(float);

        LocalTensor<T> xLocal(TPosition::VECCALC, 0, ubBufSize);
        LocalTensor<T> yLocal(TPosition::VECCALC, ubBufSize, ubBufSize);
        LocalTensor<float> tableLocal(TPosition::VECCALC, 0, tableBufSize);

        // Load table into UB
        DataCopy(tableLocal, tableGM_, TABLE_SIZE);
        PipeBarrier<PIPE_ALL>();

        float step = (maxVal_ - minVal_) / (float)(TABLE_SIZE - 1);

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32Valid = static_cast<uint32_t>(valid);

            // CopyIn
            DataCopy(xLocal, xGM_[off], u32Valid);
            PipeBarrier<PIPE_ALL>();

            // Compute GELU using lookup table
            for (int32_t i = 0; i < valid; i++) {
                float x;
                if constexpr (std::is_same_v<T, float>) {
                    x = xLocal.GetValue(i);
                } else {
                    x = static_cast<float>(xLocal.GetValue(i));
                }

                // Clamp
                if (x < minVal_) x = minVal_;
                if (x > maxVal_) x = maxVal_;

                // Map to index
                float t = (x - minVal_) / (maxVal_ - minVal_);
                int32_t idx = (int32_t)(t * (TABLE_SIZE - 1));
                if (idx < 0) idx = 0;
                if (idx >= TABLE_SIZE - 1) idx = TABLE_SIZE - 2;

                // Interpolate
                float x0 = minVal_ + (float)idx * step;
                float x1 = x0 + step;
                float y0 = tableLocal.GetValue(idx);
                float y1 = tableLocal.GetValue(idx + 1);
                float gelu = y0 + (x - x0) / step * (y1 - y0);

                if constexpr (std::is_same_v<T, float>) {
                    yLocal.SetValue(i, gelu);
                } else {
                    yLocal.SetValue(i, static_cast<T>(gelu));
                }
            }
            PipeBarrier<PIPE_ALL>();

            // CopyOut
            DataCopy(yGM_[off], yLocal, u32Valid);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    GlobalTensor<float> tableGM_;
    int32_t blockStart_;
    int32_t blockEnd_;
    int32_t totalElements_;
    float minVal_;
    float maxVal_;
};

extern "C" __global__ __aicore__ void gelu_fp32(
    GM_ADDR x, GM_ADDR y, GM_ADDR table,
    int32_t totalElements, int32_t blockSize, int32_t tasksPerCore,
    float minVal, float maxVal)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGeluTable<float> op;
    op.Init(x, y, table, totalElements, start, end, minVal, maxVal);
    op.Process();
}

extern "C" __global__ __aicore__ void gelu_fp16(
    GM_ADDR x, GM_ADDR y, GM_ADDR table,
    int32_t totalElements, int32_t blockSize, int32_t tasksPerCore,
    float minVal, float maxVal)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGeluTable<half> op;
    op.Init(x, y, table, totalElements, start, end, minVal, maxVal);
    op.Process();
}
